#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace PinPop {
 // Explicit QA only. Restores player data; a second process verifies persistence.
 public sealed class LanguageSettingsReview:MonoBehaviour {
  [Serializable]public class Saved {public string key,value;public bool exists,integer;}
  [Serializable]public class Backup {public List<Saved> values=new List<Saved>();}
  PinPopGame game;string folder,report="";int failures;Backup backup;bool restored,preserveLanguage;RenderTexture virtualScreen;
  void Check(bool ok,string message){if(!ok)failures++;report+=(ok?"PASS: ":"FAIL: ")+message+"\n";Debug.Log((ok?"PASS: ":"FAIL: ")+message);}
  IEnumerator Start(){
   game=GetComponent<PinPopGame>();folder=Environment.GetEnvironmentVariable("PINPOP_QA_DIR")??"/tmp/pinpop-language-settings-review";Directory.CreateDirectory(folder);while(PinPopSplash.Visible)yield return null;
   if(Array.IndexOf(Environment.GetCommandLineArgs(),"-language-pref-verify")>=0){backup=JsonUtility.FromJson<Backup>(File.ReadAllText(Path.Combine(folder,"preference-backup.json")));Check(PlayerPrefs.GetString(GameLocalization.PreferenceKey)=="tr","Language preference survives a real process restart");Check(GameLocalization.LanguageCode=="tr","Saved Turkish preference overrides an English device on restart");game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.3f);Check(GameObject.Find("Settings title").GetComponent<Text>().text=="AYARLAR","Restarted UI uses the saved language");Capture("restart-turkish");Restore(false);Finish();yield break;}
   backup=new Backup();foreach(string key in new[]{PinPopEconomy.SaveKey,PinPopAdventure.SaveKey,GameLocalization.PreferenceKey})Remember(key,false);foreach(string key in new[]{"Level","Coins","SwapCredits","ReducedMotion","Muted",PinPopHUD.TutorialSeenKey})Remember(key,true);File.WriteAllText(Path.Combine(folder,"preference-backup.json"),JsonUtility.ToJson(backup,true));
   int coins=game.Coins,moves=game.Moves,swaps=game.SwapCredits,attempt=game.AttemptId;var queue=game.Queue.ToArray();game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.3f);
   var initial=GameObject.Find("LANGUAGE_DROPDOWN").GetComponent<Dropdown>();Check(initial.options.Count==GameLocalization.SupportedLanguages.Count&&initial.options.Count==2,"Dropdown contains the supported languages only");Check(initial.captionText.text==GameLocalization.NativeLanguageName(GameLocalization.LanguageCode),"Initial automatic preference displays its resolved language");Check(GameObject.Find("LANGUAGE_auto")==null,"No device-language option is displayed");var caption=GameObject.Find("Language caption").GetComponent<RectTransform>();Check(Mathf.Abs(Bounds(caption).center.y-Bounds(initial.GetComponent<RectTransform>()).center.y)<1,"Language label and dropdown share one row");
   foreach(string code in new[]{"en","tr","tr","en"}){yield return Choose(code);Check(GameLocalization.PreferenceCode==code,"Settings saves explicit selection, including the initially displayed language: "+code);Check(game.Hud.SettingsVisible&&game.Paused,"Language change keeps settings open and gameplay paused");Check(GameLocalization.LanguageCode==code,"Language change takes effect immediately: "+code);Check(game.Coins==coins&&game.Moves==moves&&game.SwapCredits==swaps&&game.AttemptId==attempt&&SameQueue(queue),"Changing language preserves the attempt, moves, queue and wallet");Check(GameObject.Find("Settings title").GetComponent<Text>().text==(GameLocalization.Turkish?"AYARLAR":"SETTINGS"),"Open settings title updates");Capture("settings-home-"+code);}
   Click("LANGUAGE_DROPDOWN");yield return new WaitForSecondsRealtime(.2f);Capture("language-list");string before=GameLocalization.PreferenceCode;ClickAt(Bounds(GameObject.Find("Settings title").GetComponent<RectTransform>()).center,GameObject.Find("Blocker"));yield return new WaitForSecondsRealtime(.25f);Check(GameObject.Find("Dropdown List")==null&&game.Hud.SettingsVisible&&GameLocalization.PreferenceCode==before,"Outside tap dismisses the list without closing settings or changing language");
   var expanded=GameObject.Find("LANGUAGE_DROPDOWN").GetComponent<Dropdown>();int count=expanded.options.Count;for(int i=0;i<6;i++)expanded.options.Add(new Dropdown.OptionData("Review language "+i));Click("LANGUAGE_DROPDOWN");yield return new WaitForSecondsRealtime(.2f);var scrolling=GameObject.Find("Dropdown List").GetComponent<ScrollRect>();Check(scrolling.vertical&&scrolling.content.rect.height>scrolling.viewport.rect.height,"More language options use a bounded scrollable list");scrolling.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();var rows=GameObject.Find("Dropdown List").GetComponentsInChildren<Toggle>();Check(Bounds(rows[rows.Length-1].GetComponent<RectTransform>()).Overlaps(Bounds(scrolling.viewport)),"Last future language option can scroll into view");expanded.Hide();yield return new WaitForSecondsRealtime(.25f);expanded.options.RemoveRange(count,expanded.options.Count-count);expanded.RefreshShownValue();
   game.Hud.CloseOverlays();game.SetMenu(false);game.Hud.ShowGame();game.LoadLevel(3);game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.25f);yield return Choose("tr");Check(game.Hud.SettingsVisible&&game.Paused&&GameLocalization.Turkish,"In-game settings also switch language without resuming");Capture("settings-game-tr");game.Hud.CloseOverlays();Check(!game.Paused,"Closing settings resumes gameplay");
   foreach(var size in new[]{new Vector2Int(320,568),new Vector2Int(390,844),new Vector2Int(1170,2532)}){
    SetSize(size);yield return new WaitForSecondsRealtime(.35f);game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.2f);
    foreach(string code in new[]{"en","tr"}){GameLocalization.SetPreference(code);yield return new WaitForSecondsRealtime(.25f);var field=GameObject.Find("LANGUAGE_DROPDOWN").GetComponent<Dropdown>();var bounds=Bounds(field.GetComponent<RectTransform>());Check(bounds.width>CrispUI.Width*.7f,"Language control uses a single generous full-width row: "+size.x);Check(field.captionText.preferredWidth<=field.captionText.rectTransform.rect.width+1,"Selected native name fits without clipping: "+code+" "+size.x);Capture("language-row-"+code+"-"+size.x);Click("LANGUAGE_DROPDOWN");yield return new WaitForSecondsRealtime(.2f);var list=GameObject.Find("Dropdown List");Check(Mathf.Abs(Bounds(list.GetComponent<RectTransform>()).width-bounds.width)<1,"Language menu matches its field width");var selected=Array.Find(list.GetComponentsInChildren<Toggle>(),x=>x.isOn);Check(selected!=null&&selected.GetComponentInChildren<Text>().text==GameLocalization.NativeLanguageName(code)&&selected.graphic.GetComponentInChildren<CrispIcon>().Symbol==CrispIcon.Kind.Check,"Current language has a full-row highlight and check");Check(Bounds(list.GetComponent<RectTransform>()).xMin>=CrispUI.SafeArea.xMin&&Bounds(list.GetComponent<RectTransform>()).xMax<=CrispUI.SafeArea.xMax,"Expanded language menu stays inside screen edges");Capture("language-menu-"+code+"-"+size.x);field.Hide();yield return new WaitForSecondsRealtime(.25f);}
    game.Hud.CloseOverlays();
   }
   PlayerPrefs.SetInt("Level",0);new PinPopEconomy(new EconomySave{coins=100,swaps=3}).Save();game.ReloadEconomy();game.Adventure.Data.chests=0;game.Adventure.Save();CrispUI.ReviewReducedMotion=true;
   foreach(int level in new[]{4,9,14,19}){
    game.LoadLevel(level);typeof(PinPopGame).GetProperty("Moves").SetValue(game,11);typeof(PinPopGame).GetProperty("Cleared").SetValue(game,game.Total);typeof(PinPopGame).GetMethod("End",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,new object[]{true});yield return new WaitForSecondsRealtime(.25f);Check(game.Finished&&game.Won&&game.Adventure.LastChest==level/5+1,"Real milestone completion awards its chest at level "+(level+1));int balance=game.Coins,rights=game.SwapCredits;var stock=(int[])game.Adventure.Data.stock.Clone();
    foreach(var size in new[]{new Vector2Int(320,568),new Vector2Int(390,844),new Vector2Int(1170,2532)}){
     SetSize(size);yield return new WaitForSecondsRealtime(.35f);
     foreach(string code in new[]{"en","tr"}){GameLocalization.SetPreference(code);yield return new WaitForSecondsRealtime(.25f);Canvas.ForceUpdateCanvases();var chest=GameObject.Find("Chest rewards").GetComponent<Text>();var next=GameObject.Find("CONTINUE").GetComponent<Button>();var nextText=next.GetComponentInChildren<Text>();Check(chest.transform.IsChildOf(GameObject.Find("Victory card").transform),"Chest reward belongs to the victory card");Check(!Bounds(chest.rectTransform).Overlaps(Bounds(nextText.rectTransform)),"Chest reward cannot overlap the continue label: "+code+" "+size);Check(Bounds(chest.rectTransform).yMin>Bounds(next.GetComponent<RectTransform>()).yMax,"Chest reward has a separate row above the continue touch area");Check(GameObject.Find("Milestone reward summary")==null,"No independent reward overlay remains");Check(chest.preferredHeight<=chest.rectTransform.rect.height+1,"Chest reward text fits");Check(nextText.text==GameLocalization.Text("SONRAKİ BÖLÜM")&&next.GetComponentsInChildren<Text>().Length==1,"Continue button has exactly one correct label");var card=Bounds(GameObject.Find("Victory border").GetComponent<RectTransform>());Check(CrispUI.SafeArea.Contains(card.min)&&CrispUI.SafeArea.Contains(card.max),"Expanded milestone card stays inside the safe area");Capture("milestone-"+(level+1)+"-"+code+"-"+size.x);}
    }
    bool inventory=true;for(int i=0;i<4;i++)inventory&=game.Adventure.Data.stock[i]==stock[i];Check(game.Coins==balance&&game.SwapCredits==rights&&inventory,"Language changes and resizing never grant the milestone reward again");game.Hud.HideResult();
   }
   GameLocalization.SetPreference("tr");yield return new WaitForSecondsRealtime(.1f);preserveLanguage=failures==0;Restore(preserveLanguage);Finish();
  }
  bool SameQueue(int[] values){if(game.Queue.Count!=values.Length)return false;for(int i=0;i<values.Length;i++)if(game.Queue[i]!=values[i])return false;return true;}
  void Remember(string key,bool integer){backup.values.Add(new Saved{key=key,exists=PlayerPrefs.HasKey(key),integer=integer,value=integer?PlayerPrefs.GetInt(key).ToString():PlayerPrefs.GetString(key)});}
  void Restore(bool keepLanguage){if(restored||backup==null)return;foreach(var value in backup.values){if(keepLanguage&&value.key==GameLocalization.PreferenceKey)continue;if(!value.exists)PlayerPrefs.DeleteKey(value.key);else if(value.integer)PlayerPrefs.SetInt(value.key,int.Parse(value.value));else PlayerPrefs.SetString(value.key,value.value);}PlayerPrefs.Save();restored=true;}
  void OnDestroy(){Restore(preserveLanguage);CrispUI.ReviewSize=null;CrispUI.ReviewSafeArea=null;}
  void Finish(){File.WriteAllText(Path.Combine(folder,Array.IndexOf(Environment.GetCommandLineArgs(),"-language-pref-verify")>=0?"persistence-verification.txt":"verification.txt"),report);Application.Quit(failures==0?0:1);}
  IEnumerator Choose(string code){Click("LANGUAGE_DROPDOWN");yield return new WaitForSecondsRealtime(.2f);var popup=GameObject.Find("Dropdown List");var field=GameObject.Find("LANGUAGE_DROPDOWN").GetComponent<LanguageDropdown>();Check(Mathf.Abs(Bounds(field.Arrow).center.y-Bounds(field.GetComponent<RectTransform>()).center.y)<1,"Disclosure arrow rotates around its center");Check(popup!=null,"Language dropdown opens");if(popup==null)yield break;var viewport=Bounds(popup.GetComponent<ScrollRect>().viewport);foreach(var row in popup.GetComponentsInChildren<Toggle>()){var bounds=Bounds(row.GetComponent<RectTransform>());Check(bounds.yMin>=viewport.yMin-.5f&&bounds.yMax<=viewport.yMax+.5f,"Language row is fully visible, including vertical padding");}var option=Array.Find(popup.GetComponentsInChildren<Toggle>(),x=>x.GetComponentInChildren<Text>().text==GameLocalization.NativeLanguageName(code));Check(option!=null,"Dropdown offers "+code);if(option!=null)ClickAt(Bounds(option.GetComponent<RectTransform>()).center,option.gameObject);yield return new WaitForSecondsRealtime(.25f);Check(GameObject.Find("Dropdown List")==null&&GameObject.Find("Blocker")==null,"Selecting a language removes the popup and input blocker");}
  void Click(string name){var target=GameObject.Find(name);ClickAt(Bounds(target.GetComponent<RectTransform>()).center,target);}
  void ClickAt(Vector2 position,GameObject expected){Canvas.ForceUpdateCanvases();var pointer=new PointerEventData(EventSystem.current){position=position,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);var target=hits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject);Check(expected!=null&&target==expected,"Actual pointer raycast reaches "+expected?.name);if(target==expected&&target!=null)ExecuteEvents.Execute(target,pointer,ExecuteEvents.pointerClickHandler);}
  Rect Bounds(RectTransform rect){var corners=new Vector3[4];rect.GetWorldCorners(corners);var low=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,corners[0]);var high=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,corners[2]);return Rect.MinMaxRect(low.x,low.y,high.x,high.y);}
  void SetSize(Vector2Int size){CrispUI.ReviewSize=size;CrispUI.ReviewSafeArea=size.x==1170?new Rect(0,102,1170,2289):new Rect(0,0,size.x,size.y);if(virtualScreen!=null){virtualScreen.Release();Destroy(virtualScreen);}virtualScreen=new RenderTexture(size.x,size.y,24);virtualScreen.Create();game.Camera.targetTexture=virtualScreen;game.Hud.UICamera.targetTexture=virtualScreen;}
  void Capture(string name){Canvas.ForceUpdateCanvases();int w=CrispUI.Width,h=CrispUI.Height;var rt=RenderTexture.GetTemporary(w,h,24);var previous=RenderTexture.active;var world=game.Camera.targetTexture;var ui=game.Hud.UICamera.targetTexture;game.Camera.targetTexture=rt;game.Hud.UICamera.targetTexture=rt;game.Camera.Render();game.Hud.UICamera.Render();RenderTexture.active=rt;var image=new Texture2D(w,h,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,w,h),0,0);image.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),image.EncodeToPNG());game.Camera.targetTexture=world;game.Hud.UICamera.targetTexture=ui;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);Destroy(image);}
 }
}
#endif
